const PACKAGE={"id":"BFSdual_LF06_Lernpfad_LS6_6","ls":"6.6","title":"Lernpfadübung · LS 6.6 · Werbemittel für beide Standorte gestalten","version":"1.0","source":"Fachbereiche/BFSdual/LF06/LS_6_6_Werbemittel_gestalten.md"};
const COMP=[["Fachkompetenz","Ich gestalte dieselbe Werbebotschaft für zwei Zielgruppen und zwei Werbeformate. Ich prüfe meine Aussagen zu den Produkten mit den Produktblättern."],["Personalkompetenz","Ich plane so, dass mein Entwurf vor der Freigabe geprüft werden kann."],["Sozialkompetenz","Ich nutze Rückmeldungen dazu, wie verständlich der Text ist. Ich erkläre, warum ich bestimmte Formulierungen auswähle."],["Methodenkompetenz","Ich prüfe eine Werbeaussage mit einer passenden Quelle."],["Medienkompetenz","Ich gestalte Text, Bild und Blickfang passend zum jeweiligen Werbeträger."]];
const BANK=[{"title":"Zwei Rückmeldungen einordnen","scene":"Global Bike bereitet eine gemeinsame Frühjahrsaktion vor. Sarah aus dem Marketing schaut auf die Verständlichkeit von Newsletter und Eingangsschild. Alexander aus dem Einkauf prüft die Produktangaben.","ask":"Wie nutzt das Team die beiden Rückmeldungen für die Überarbeitung?","options":["Sarahs Rückmeldung zum ersten Eindruck nutzen und die Botschaft in beiden Formaten deutlich zeigen.","Das Produktblatt zu Alexanders Einwand heranziehen und seine Korrektur mit dem passenden Beleg erklären.","Nur Alexanders Sicht berücksichtigen, weil Verständlichkeit bei einer Werbung unwichtig ist.","Beide Rückmeldungen als Vorgabe für ein einziges Werbemittel behandeln.","Im Team festhalten, welche Stelle wegen besserer Lesbarkeit und welche wegen eines falschen Versprechens geändert wird.","Sarah bitten, die Passform allein nach der Wirkung des Textes zu bestätigen."],"answer":[0,1,4],"why":"Sarah und Alexander schauen auf verschiedene Kriterien. Das Team kann die Verständlichkeit verbessern und technische Änderungen mit dem passenden Produktblatt begründen.","hint":"Ordne beide Rückmeldungen jeweils einem Prüfkriterium zu.","steps":"Lies die Aussagen von Sarah und Alexander. Frage, welche Rückmeldung bei der Gestaltung und welche bei der Prüfung hilft.","example":"Das Team kann die Überschrift kürzen und unabhängig davon ein falsches Merkmal aus einer Zeichnung entfernen.","c":2,"sourceRefs":["Handlungssituation","M1","M2"],"id":0,"l":1,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zielgruppen erkennen","scene":"Sarah will, dass beide Werbemittel schnell verständlich sind. M1 beschreibt für jeden Laden, wer angesprochen werden soll.","ask":"Was passt zu den Zielgruppen im Fall?","options":["Das Eingangsschild richtet sich hauptsächlich an Menschen, die auf dem Weg zur Arbeit bei Block vorbeifahren.","Der Newsletter spricht Menschen an, die im Alltag Rad fahren.","Die Bike Arena möchte Familien und Menschen erreichen, die in der Freizeit Rad fahren.","Block möchte Menschen mit Interesse an Zubehör beraten.","Das Eingangsschild richtet sich ausschließlich an Personen, die eine Reparatur gebucht haben.","Am Eingang in Leer sollen Kundinnen und Kunden erst auf einen Newsletter zum Auffinden der Aktionsfläche warten."],"answer":[1,2,3],"why":"Block spricht Alltagsradelnde an und bietet Beratung an. Die Bike Arena erreicht Familien und Freizeitradelnde beim Betreten und soll sie zur Aktionsfläche leiten.","hint":"Überlege, wo die Kundschaft den Hinweis liest und was sie dort braucht.","steps":"Vergleiche in M1 die beiden Zeilen zu Zielgruppe und Nutzen; lies bei Bedarf die Stimmen aus M4.","example":"Eine Familie im Laden braucht eine klarere Wegangabe als jemand, der sich vorab zur Beratung informieren möchte.","c":4,"sourceRefs":["M1","M4"],"id":1,"l":1,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die gemeinsame Botschaft","scene":"Für den Newsletter und das Eingangsschild gibt Global Bike einen Werbeauftrag aus.","ask":"Welche Regeln betreffen beide Fassungen?","options":["Beide verwenden die Botschaft „Frühjahrsstart mit Fahrradzubehör von Global Bike“.","Die gesamte Aktion läuft von Dienstag bis Samstag derselben Woche.","Beide Fassungen müssen dieselben vier Artikel einzeln vorstellen.","Preise dürfen genannt werden, wenn sie Platz sparen.","Die Ausstattung auf einer Zeichnung muss zu den Produktblättern passen.","Der Beratungsaufruf für Aurich muss unverändert auf das Schild in Leer kopiert werden."],"answer":[0,1,4],"why":"Beide Fassungen zeigen die gemeinsame Frühjahrsbotschaft, denselben Zeitraum und belegbare Ausstattung. Artikel, Zielgruppe und Handlungsaufforderung unterscheiden sich nach Standort.","hint":"Suche im Werbeauftrag die Vorgaben unterhalb der Tabelle.","steps":"Markiere, was für beide Läden genannt wird und was nur in einer Spalte steht.","example":"Das Thema kann gemeinsam bleiben, auch wenn einmal zur Beratung und einmal zur Selbstbedienung eingeladen wird.","c":0,"sourceRefs":["M1","M2"],"id":2,"l":1,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Mit dem Handy lesen","scene":"Block verschickt einen Newsletter an Kundinnen und Kunden, die oft auf dem Handy lesen.","ask":"Welche Vorgaben gelten für den Block-Newsletter?","options":["Eine gut erkennbare Betreffzeile.","Ein kurzer Absatz bis 75 Wörter.","Ein A4-Schild im Hochformat als das gewünschte Ergebnis.","Ein etwa 7 cm breiter Handyrahmen im Unterricht.","Ein Plan für die Wege im Hauptgang der Bike Arena.","Ein Text ausschließlich aus technischen Daten ohne Handlungsaufforderung."],"answer":[0,1,3],"why":"Der Unterrichtsentwurf für Block braucht eine Betreffzeile, höchstens 75 Wörter im kurzen Absatz und einen klaren nächsten Schritt. Überprüft wird er in einer Handyansicht mit ungefähr 7 cm Breite.","hint":"Lies die Newsletter-Spalte im Werbeauftrag.","steps":"Trenne Hinweise zur Form von den Anforderungen an Inhalt und nächsten Schritt.","example":"Ein Betreff steht im Posteingang. Der Absatz wird anschließend in der geöffneten Nachricht gelesen.","c":4,"sourceRefs":["M1","M5"],"id":3,"l":1,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Vom Eingang aus schauen","scene":"Das Schild erscheint in einem Aufsteller am Eingang der Bike Arena. Leserinnen und Leser sind auf dem Weg in den Laden.","ask":"Welche Vorgaben beschreiben diesen Entwurf?","options":["Ein Haupttext, der aus mehreren längeren Absätzen besteht.","Eine gut lesbare Überschrift, die zuerst auffällt.","Eine klare Wegangabe zur markierten Aktionsfläche am Hauptgang.","Die Handyansicht ist das verbindliche Prüfformat des Schildes.","Ein A4-Hochformat, dessen wichtige Angaben aus wenigen Schritten Abstand zu lesen sind.","Alle Zusatzdaten aus M2 sollen gleich groß auf das Schild."],"answer":[1,2,4],"why":"Das Schild soll aus ein paar Schritten Entfernung schnell verstanden werden. Eine auffällige Überschrift, wenige Angaben und ein konkreter Weg zur Aktionsfläche passen dazu.","hint":"Versetze dich an den Eingang. Was kannst du dort bequem lesen?","steps":"Gehe in M1 die Zeilen Format, Umfang und Nutzen für die Bike Arena durch.","example":"Eine kleine Schrift kann am Tisch lesbar sein, am Eingang aber untergehen.","c":4,"sourceRefs":["M1","M5"],"id":4,"l":1,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die passende Quelle","scene":"Alexander legt im Fall die Produktblätter neben die ersten Werbeentwürfe.","ask":"Welche Aussagen erklären, wie man eine Produktaussage belegt?","options":["Der erste Entwurf belegt seine eigenen Versprechen.","Die Aussage muss mit einer geprüften Angabe zum richtigen Artikel übereinstimmen.","Eine Kundenstimme kann Wünsche zeigen, aber keine unbekannte Produkteigenschaft bestätigen.","Wenn das Marketing die Angabe schön formuliert, wird sie dadurch belegbar.","Die Artikelnummer hilft, ein ähnliches Modell von dem beworbenen Produkt zu unterscheiden.","Eine Zeichnung eines anderen Pumpenmodells reicht, solange das Bild gut lesbar ist."],"answer":[1,2,4],"why":"Geprüfte Angaben zum richtigen Artikel stehen in M2. Kundenstimmen und Entwürfe helfen bei der Gestaltung, liefern aber keine technischen Produktbelege.","hint":"Achte darauf, wozu M2 und M4 jeweils dienen.","steps":"Suche zuerst den beworbenen Artikel und vergleiche dann die Aussage mit genau seiner Zeile in M2.","example":"Eine Person kann eine Druckanzeige wünschen. Das belegt noch keine Anzeige an einer bestimmten Pumpe.","c":3,"sourceRefs":["Handlungssituation","M2","M4"],"id":5,"l":1,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Den L10-Entwurf zur Prüfung geben","scene":"Im ersten Newsletter steht, dass das L10 LED-Lichtset mit einem Netzteil geliefert wird. Die prüfende Person braucht die aktuelle Fassung vor dem Freigabetermin.","ask":"Wie bereitest du deine eigene Aufgabe vor, damit die Angabe rechtzeitig geprüft werden kann?","options":["Die Aussage im Entwurf markieren, die L10-Zeile zum Lieferumfang dazulegen und den Entwurf rechtzeitig zur Prüfung geben.","Warten, bis der Newsletter versendet ist, und erst dann die Produktangaben vorlegen.","Die Fassung schon freigeben, weil das Wort Netzteil verständlich ist.","Einen Termin für die Rückmeldung und Zeit zum Ändern vor der Freigabe einplanen.","Der prüfenden Person nur ein Bild des L10 schicken und nicht angeben, welche Textstelle gemeint ist.","Die Prüfung auf einen späteren Werbeauftrag verschieben, damit dieser Entwurf pünktlich rausgeht."],"answer":[0,3],"why":"Der früh vorliegende Entwurf mit markierter Stelle und Produktblatt lässt sich gezielt prüfen. M2 nennt ein Ladekabel im Lieferumfang. Zeit vor der Freigabe ermöglicht, das unbelegte Netzteil zu streichen.","hint":"Berücksichtige sowohl die Vorbereitung der Prüfung als auch die mögliche Korrektur.","steps":"Denke rückwärts von der Freigabe. Bestimme, welche Unterlagen zur Prüfung bereitliegen und wann du die Rückmeldung brauchst.","example":"Ein kurzer Änderungszeitraum gehört zwischen Rückmeldung und Freigabe, wenn Text oder Bild noch korrigiert werden können.","c":1,"sourceRefs":["Handlungssituation","M2","M3"],"id":6,"l":1,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die Funktion der Rahmentasche","scene":"Eine Kundin möchte ihre Schlüssel und anderes Kleinzubehör in einer Tasche am Fahrrad unterbringen.","ask":"Welche belegbaren Informationen passen zur T30?","options":["Die Tasche fasst 1,2 Liter.","Sie ist aus wasserabweisendem Material.","Sie ist für längeres Untertauchen geprüft.","Sie wird mit verstellbaren Klettbändern befestigt.","Das Produktblatt garantiert Passform in jedes Rahmendreieck.","Ohne weitere Prüfung ist jeder Inhalt bei Starkregen sicher trocken."],"answer":[0,1,3],"why":"Die T30 fasst 1,2 Liter, ist wasserabweisend und wird mit verstellbaren Klettbändern befestigt. Platz am Rahmen und Verhalten bei Starkregen sind andere Fragen.","hint":"Überlege, was das Wort „wasserabweisend“ konkret belegt.","steps":"Suche in M2 nach Volumen, Befestigung und Material. Prüfe, ob stärkere Versprechen dort wirklich stehen.","example":"Eine wasserabweisende Oberfläche sagt nichts über garantierten Schutz bei dauerhaftem Starkregen.","c":0,"sourceRefs":["M2","M3","M4"],"id":7,"l":1,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die Minipumpe im Produktblatt","scene":"Auf der ersten Skizze für Leer hat die P50 eine runde Anzeige. Alexander bezweifelt, dass sie zur Pumpe gehört.","ask":"Welche Angaben zur P50 sind laut M2 richtig?","options":["Sie passt zu Sclaverand- und Autoventilen.","Sie hat ein eingebautes Manometer.","Ihr Höchstdruck beträgt 6 bar.","Eine Rahmenhalterung wird mitgeliefert.","Sie passt zu allen Ventilen.","Ein Blitzlicht zur Beleuchtung gehört zum Lieferumfang."],"answer":[0,2,3],"why":"Das Produktblatt der P50 nennt Sclaverand- und Autoventile, 6 bar Höchstdruck und eine Rahmenhalterung. Es nennt ausdrücklich keine Druckanzeige.","hint":"Eine Angabe in der Zeichnung braucht genauso einen Beleg wie eine Angabe im Text.","steps":"Suche die Zeile P50. Vergleiche erst die technischen Angaben und danach den Lieferumfang.","example":"Wer die eingebaute Anzeige eines ähnlichen Modells zeichnet, kann Kundschaft über die P50 täuschen.","c":3,"sourceRefs":["Handlungssituation","M2","M3"],"id":8,"l":1,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was das Band tut","scene":"Im ersten Schildentwurf steht, dass das B80 Reflektorband selbst leuchtet.","ask":"Was sagt das Produktblatt über das B80?","options":["Das Band besitzt eine eingebaute LED.","Der Umfang ist zwischen 20 und 40 cm einstellbar.","Das Band wirft Licht zurück, das darauf fällt.","Das B80 wird mit USB-C aufgeladen.","Das Band ist mit einem Netzteil erhältlich.","Zum Band gehört keine eigene Beleuchtung."],"answer":[1,2,5],"why":"Das B80 ist ein einstellbares Reflektorband. Es wirft auftreffendes Licht zurück und hat keine eigene Beleuchtung.","hint":"Überlege, woher das Licht kommt, das zu sehen ist.","steps":"Vergleiche „wirft Licht zurück“ aus M2 mit „leuchtet selbst“ aus M3.","example":"Ein Lichtstrahl kann vom Band zurückgeworfen werden, ohne dass das Band selbst Licht erzeugt.","c":0,"sourceRefs":["M2","M3"],"id":9,"l":1,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Vor der Freigabe","scene":"Jan braucht heute zwei einsatzfähige Fassungen. Der Werbeauftrag und die Produktblätter liegen bereit.","ask":"Welche Schritte will Jan mit einem sinnvollen Ablauf ermöglichen?","options":["Den Entwurf rechtzeitig an die prüfende Person geben.","Die veröffentlichte Fassung prüfen, nachdem die Werbung bereits verteilt wurde.","Text und Bild vor der Freigabe mit dem passenden Produktblatt abgleichen.","Nur den ältesten Entwurf ablegen, damit keine Änderungen mehr nötig werden.","Bei offenen Aussagen genügend Zeit für eine Korrektur einplanen.","Technische Angaben ungeprüft übernehmen, sobald der Text fertig aussieht."],"answer":[0,2,4],"why":"Ein Entwurf muss vor der Freigabe zur Prüfung vorliegen. Danach bleibt Zeit, nicht belegte Aussagen oder Zeichnungen zu korrigieren.","hint":"Gehe im Kopf rückwärts vom Zeitpunkt der Freigabe.","steps":"Ordne die Arbeit in Entwerfen, Prüfen, Korrigieren und Freigeben.","example":"Eine schön gestaltete Fassung kann noch eine Druckanzeige zeigen, die das Produkt nicht hat.","c":1,"sourceRefs":["Handlungssituation","M2","M5"],"id":10,"l":1,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Rückmeldung nutzen","scene":"Sarah möchte, dass man den Newsletter am Handy und das Eingangsschild aus ein paar Schritten Entfernung schnell versteht.","ask":"Welche Rückfragen an Testlesende helfen beim Überarbeiten?","options":["Worum geht es nach einem ersten kurzen Blick?","Welche technischen Versprechen gefallen dir am besten, selbst wenn sie unbelegt sind?","Was würdest du nach dem Lesen tun oder wohin würdest du gehen?","Welche Stelle war schwer verständlich oder zu klein?","Wie viele verschiedene Preisangebote sollen wir ergänzen, obwohl M1 keine Preise verlangt?","Können wir die korrekte Artikelnummer ersetzen, wenn die Formulierung gefälliger klingt?"],"answer":[0,2,3],"why":"Rückmeldungen zu Botschaft, nächstem Schritt und Lesbarkeit zeigen, was verständlicher werden sollte. Technische Angaben werden weiterhin am Produktblatt geprüft.","hint":"Frage nach dem, was die Person tatsächlich erkannt hat.","steps":"Prüfe bei jeder Frage, ob du aus der Antwort einen klaren Überarbeitungsschritt ableiten kannst.","example":"Wenn jemand die Aktion erkennt, aber den Weg nicht findet, braucht das Schild eine bessere Wegangabe.","c":2,"sourceRefs":["Handlungssituation","M1","M4","M5"],"id":11,"l":1,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Betreff und nächster Schritt","scene":"Der Newsletter für Block soll Menschen mit Alltagsrädern zur Beratung einladen.","ask":"Welche Textbausteine passen am besten in die Fassung für Aurich?","options":["„Dienstag bis Samstag: Frühjahrsstart mit Fahrradzubehör bei Block“ als Betreff.","„Nur heute in Leer: Extrapreise für P50“ als Betreff.","„Schaut bei Block in Aurich vorbei und lasst euch zur passenden Halterung beraten.“","„Zum Hauptgang in der Bike Arena“ als einziger Handlungsaufruf.","„Informationen zu allem“ als Betreff, ohne die Aktion zu nennen.","„Probiert an der Aktionsfläche bei Block aus, ob die Rahmentasche am Rad Platz hat.“"],"answer":[0,2,5],"why":"Die ausgewählten Bausteine zeigen das Thema im Posteingang und leiten zu Beratung oder Ausprobieren in Aurich. P50 und Hauptgang gehören in den Auftrag für Leer.","hint":"Suche nach einer Handlung, die Menschen tatsächlich bei Block ausführen können.","steps":"Prüfe jede Zeile nach Aktionsbezug, Ort und Handlung. Ein Betreff muss schon vor dem Öffnen etwas verraten.","example":"Ein konkreter Beratungsaufruf sagt mehr als „Wir freuen uns auf euch“.","c":4,"sourceRefs":["M1","M4"],"id":12,"l":2,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Betreff und Absatz auseinanderhalten","scene":"Übungsvariante: Der Entwurf für Block hat einen klaren Betreff, aber der Absatz ist 98 Wörter lang. Die Wegangabe für die Bike Arena steht am Ende des Absatzes.","ask":"Welche Änderungen passen?","options":["Den Absatz auf höchstens 75 Wörter kürzen und die wichtigsten Angaben im Handyrahmen prüfen.","Den Betreff streichen, damit der Absatz mehr Platz im Posteingang bekommt.","Die Wegangabe zur Bike Arena aus Blocks Newsletter streichen.","Die Beratung bei Block als klaren nächsten Schritt stehen lassen.","Den Absatz vollständig auf das Eingangsschild kopieren, um Text zu sparen.","Den zu langen Absatz durch eine Preisübersicht ersetzen."],"answer":[0,2,3],"why":"Der klare Betreff bleibt. Der Absatz wird kürzer und gibt einen für Block passenden Hinweis auf Beratung oder Aktionsfläche. Der Weg am Hauptgang gehört zur Bike Arena.","hint":"Trenne die Vorgaben zum Format von denen zum jeweiligen Laden.","steps":"Markiere im Absatz alle Stellen, die dem Laden und Inhalt des Auftrags dienen. Kürze oder streiche den Rest.","example":"Das Streichen eines fremden Standortes kann den Text gleichzeitig kürzer und klarer machen.","c":4,"sourceRefs":["M1","M5"],"id":13,"l":2,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Der dickere Lenker","scene":"Übungsvariante: Eine Person fragt, ob sie das L10 an einem runden Lenker mit 35 mm Durchmesser befestigen kann.","ask":"Welche Antworten sind für den Newsletter oder die Beratung sachlich tragfähig?","options":["„Das L10 passt an alle runden Lenker, auch an 35 mm.“","„Die vordere Halterung passt an runde Lenker mit 22–32 mm Durchmesser.“","„Für 35 mm belegt das Produktblatt keine passende Halterung.“","„Dem Set liegt ein Netzteil bei, das die Montage vereinfacht.“","„Lasst euch bei Block zur passenden Befestigung beraten.“","„Die Lampe ist unbrauchbar für jedes ältere Fahrrad.“"],"answer":[1,2,4],"why":"Die belegte Spannweite endet bei 32 mm. Ein 35-mm-Lenker liegt außerhalb dieser Angabe. Der Beratungsaufruf gibt eine hilfreiche Alternative, ohne Passform zu versprechen.","hint":"Vergleiche 35 mm nur mit der Spannweite der richtigen Halterung.","steps":"Prüfe Lenkerform, Mindestmaß und Höchstmaß in M2. Trenne Auskunft über dieses Produkt von der Einladung zur Beratung.","example":"Eine Angabe von 22–32 mm sagt nichts über die allgemeine Eignung für alte oder neue Fahrräder.","c":0,"sourceRefs":["M1","M2","M4"],"id":14,"l":2,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Starkregen im Entwurf","scene":"Aus M3: „Die T30 hält selbst bei Starkregen garantiert alles trocken.“","ask":"Welche Änderungen kann Alexander beim Aussagencheck begründen?","options":["Die Garantie stehen lassen, weil wasserabweisend und wasserdicht dasselbe sind.","Die Aussage mit „Die T30 ist wasserabweisend“ ersetzen.","Bei Bedarf 1,2 Liter Volumen als andere belegte Eigenschaft nennen.","Den Zusatz „für jedes Rahmendreieck“ ergänzen, um das Versprechen konkreter zu machen.","Die Formulierung „wasserdicht bis 10 Meter“ übernehmen, wenn sie kürzer ist.","Im Aussagencheck das Produktblatt T30 und die ersetzte Aussage festhalten."],"answer":[1,2,5],"why":"Das Material ist laut M2 wasserabweisend. Eine Starkregen-Garantie ist unbelegt. Die 1,2 Liter sind nachprüfbar und die Änderung kann im Aussagencheck dokumentiert werden.","hint":"Bleib bei den Wörtern, die M2 belegt.","steps":"Markiere den überzogenen Teil im alten Satz und schreibe eine belegbare Fassung in die Liste.","example":"„Wasserabweisend“ und „hält bei Starkregen alles trocken“ sind Zusagen mit unterschiedlicher Reichweite.","c":3,"sourceRefs":["M2","M3","M5"],"id":15,"l":2,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Bilder richtig prüfen","scene":"Das Eingangsschild zeigt die P50 mit einer runden Druckanzeige. In einem anderen Entwurf ist ein Bild von einer Pumpe mit Anzeige zu sehen.","ask":"Was hilft vor der Freigabe?","options":["Das Bild als Dekoration behalten, solange der Text keine Anzeige verspricht.","Die Druckanzeige im Bild entfernen.","Das Bild bei Unsicherheit durch ein Feld mit Produktname und Artikelnummer ersetzen.","Eine Skizze ohne Anzeige mit M2 abgleichen, bevor sie übernommen wird.","Das Bild durch den Satz „mit genauer Druckanzeige“ erklären.","Die Artikelnummer P50 weglassen und trotzdem auf genau dieses Modell verweisen."],"answer":[1,2,3],"why":"Auch ein Bild kann eine Eigenschaft versprechen. Für die P50 sind eine passende Skizze oder ein eindeutig beschriftetes Produktfeld zulässig. Die Anzeige gehört nicht dazu.","hint":"Frage, was eine Kundin allein aus dem Bild schließen würde.","steps":"Prüfe die sichtbaren Teile mit der P50-Zeile. Nutze bei Unsicherheit die einfache Alternative aus M1.","example":"Ein Schild kann die Pumpe eindeutig bewerben, auch wenn es ihren Produktnamen statt eines Bildes zeigt.","c":4,"sourceRefs":["M1","M2","M3"],"id":16,"l":2,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ventile verständlich angeben","scene":"Die Person in M4 braucht eine Pumpe für verschiedene Fahrräder. Das Schild verspricht bisher „für alle Ventile“.","ask":"Welche Formulierungen oder Angebote sind bei der P50 möglich?","options":["„Passend für Sclaverand- und Autoventile.“","„Passt nur an Reifen mit einer Breite von mindestens 35 mm.“","„Vergleicht am Hauptgang, ob die P50 zu eurem Ventiltyp passt.“","„6 bar Höchstdruck“ als belegte Produkteigenschaft.","„Die P50 hat ein Manometer, das die Ventilart erkennt.“","„Die P50 passt sicher auch zu jedem dritten Ventiltyp.“"],"answer":[0,2,3],"why":"Die P50 passt zu den zwei belegten Ventiltypen und hat 6 bar Höchstdruck. Der Vergleich vor Ort hilft, ohne weitere Kompatibilität zu versprechen.","hint":"Suche in M2 nach Ventilarten. Eine Druckangabe beantwortet eine andere Frage.","steps":"Gleiche die genannten Typen mit M2 ab und prüfe, was Kundschaft vor Ort selbst vergleichen kann.","example":"„Für alle“ ist auch dann zu weit, wenn zwei häufige Ventiltypen passen.","c":0,"sourceRefs":["M1","M2","M3","M4"],"id":17,"l":2,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"B80 ohne falsche Versprechen","scene":"Übungsvariante: Für das Schild soll ein sehr kurzer, richtiger Satz zum B80 entstehen.","ask":"Welche Aussagen wären geeignet?","options":["„B80: leuchtet selbst, auch ohne Licht von außen.“","„B80: wirft auftreffendes Licht zurück.“","„B80: mit eingebauter USB-C-Leuchte.“","„B80: Umfang von 20 bis 40 cm einstellbar.“","„B80: bringt das eigene Licht gleich mit.“","„B80: für jeden Arm oder Rahmen ohne Nachmessen garantiert passend.“"],"answer":[1,3],"why":"Die geprüfte Funktion ist das Zurückwerfen auftreffenden Lichts. 20 bis 40 cm ist der Einstellbereich. Das Band hat keine eigene Beleuchtung und die Spanne trägt keine allgemeine Passformgarantie.","hint":"Prüfe ausdrücklich die Quelle des sichtbaren Lichts.","steps":"Vergleiche jede kurze Formulierung mit der B80-Zeile. Achte außerdem auf den Unterschied zwischen Maßangabe und Garantie.","example":"Ein einstellbarer Umfang gilt nur innerhalb der genannten Grenzen.","c":3,"sourceRefs":["M2","M3"],"id":18,"l":2,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Den Weg erkennen","scene":"Übungsvariante: Testlesende in Leer verstehen das Schild mit „Hier entlang zur Zubehöraktion“, finden aber die Aktionsfläche nicht.","ask":"Wie könnt ihr das Problem aus M1 mit der Rückmeldung lösen?","options":["„Aktionsfläche am Hauptgang“ deutlich als Wegziel nennen.","Das Wort „hier“ beibehalten und die Angabe zum Hauptgang weglassen.","Die Wegangabe aus dem Blickabstand erneut lesen lassen.","Das P50-Produktblatt ungekürzt als Schild aufhängen.","Je nach tatsächlichem Aufstellort einen eindeutigen Richtungspfeil einsetzen und prüfen.","Kundinnen und Kunden erst im Newsletter von Block nach dem Weg suchen lassen."],"answer":[0,2,4],"why":"Die Angabe „am Hauptgang“ macht das Ziel konkret. Ein überprüfter Pfeil kann den Weg zusätzlich zeigen. Ein Lesetest zeigt, ob Kundschaft die neue Angabe wahrnimmt.","hint":"Klärt den Unterschied zwischen dem Ziel und der Richtung dorthin.","steps":"Ergänze das Wegziel und teste das Schild aus wenigen Schritten Entfernung. Achte auf den tatsächlichen Ort beim Zeichnen eines Pfeils.","example":"Ein alleinstehender Pfeil zeigt eine Richtung, benennt aber kein Ziel.","c":2,"sourceRefs":["M1","M3","M4","M5"],"id":19,"l":2,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Belege in die Prüfliste schreiben","scene":"Übungsvariante: Im Aussagencheck steht bisher nur „P50: korrigiert“. Jan möchte verstehen, was sich geändert hat.","ask":"Welche Angaben machen den Eintrag überprüfbar?","options":["Die ursprüngliche Aussage, zum Beispiel „mit Druckanzeige“.","Den passenden Beleg aus der P50-Zeile in M2.","Einen anderen Artikel als Ersatzbeleg, damit die Liste kürzer bleibt.","Die Entscheidung, die unbelegte Angabe zu streichen.","Die fertige Formulierung oder den Vermerk, dass die Anzeige auch aus dem Bild entfernt ist.","Nur den Namen der Person, die das Schild am schnellsten gelesen hat."],"answer":[0,1,3,4],"why":"Mit alter Aussage, passendem Beleg, Entscheidung und neuer Fassung lässt sich die Korrektur nachvollziehen. Beim Bild gilt dieselbe Prüfung.","hint":"Nutze die Spalten des Aussagenchecks in M5.","steps":"Gehe vom ursprünglichen Versprechen zu seinem Beleg und vom Beleg zur Entscheidung. Halte auch die Änderung im Bild fest.","example":"„Korrigiert“ allein verrät nicht, ob der falsche Zusatz an einer anderen Stelle geblieben ist.","c":3,"sourceRefs":["M2","M3","M5"],"id":20,"l":2,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Mit Rückmeldung weiterarbeiten","scene":"Übungsvariante: Eine Testperson findet den Beratungsaufruf gut. Sie lässt aber „L10 für jeden Lenker“ als einfachere Formulierung vorschlagen.","ask":"Welche Antworten zeigen, dass ihr die Rückmeldung nutzt und fachlich sauber bleibt?","options":["Den Aufruf zur Beratung beibehalten, da er verständlich ist und zum Auftrag passt.","Die falsche Vereinfachung übernehmen, weil Testlesende den Text sonst umständlich finden.","Die Maße kompakt und korrekt als „für runde Lenker mit 22–32 mm Durchmesser“ schreiben.","Erklären, welche Formulierung sich auf M2 stützt und warum das stärkere Versprechen ausscheidet.","Die Rückmeldung verwerfen und sämtliche Texte unverändert lassen.","Die fehlende Angabe durch einen garantierten Kaufnutzen ersetzen."],"answer":[0,2,3],"why":"Rückmeldung hilft bei Verständlichkeit und Handlung. Die Aussage zur Passform muss weiterhin zum Produktblatt passen. Eine kurze, genaue Formulierung erfüllt beides.","hint":"Trenne die Rückmeldung zur verständlichen Sprache von einer Behauptung über das Produkt.","steps":"Markiere erst, was am Entwurf funktioniert. Prüfe jede vorgeschlagene neue Produkteigenschaft separat mit M2.","example":"Eine kürzere Formulierung ist gut, solange sie die Reichweite der Aussage nicht unbemerkt erweitert.","c":2,"sourceRefs":["M1","M2","M5"],"id":21,"l":2,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Puffer vor Freigabe einbauen","scene":"Übungsvariante: Das Team braucht noch Zeit für Gestaltung, Lesetest und Aussagencheck. Jan erwartet heute beide fertigen Fassungen.","ask":"Welche Absprachen helfen, rechtzeitig fertig zu sein?","options":["Eine gemeinsame Zwischenzeit für die ersten Entwürfe festlegen.","Erst zur Freigabe prüfen, welche Angaben noch fehlen.","Parallel einen Entwurf prüfen und für den anderen die benötigten Produktangaben heraussuchen.","Vor dem Abgabetermin Zeit für eine Korrekturrunde einplanen.","Korrekturen nur durchführen, wenn ein Laden die Werbung bereits eingesetzt hat.","Fragen zu Bildern und Aussagen bis nach der Freigabe sammeln."],"answer":[0,2,3],"why":"Ein früher Zwischenstand, verteilte Aufgaben und eine eingeplante Korrekturrunde helfen euch, zwei überprüfte Fassungen pünktlich vorzulegen.","hint":"Denke vom Abgabetermin zurück bis zur ersten Prüfung.","steps":"Plane Entwurf, Rückmeldung, Korrektur und Freigabe mit festen Übergaben. Prüfe, welche Schritte unabhängig voneinander starten können.","example":"Zwei Personen können gleichzeitig an verschiedenen Fassungen arbeiten, wenn sie denselben Werbeauftrag nutzen.","c":1,"sourceRefs":["Handlungssituation","M1","M2","M5"],"id":22,"l":2,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Freigabe für beide Fassungen","scene":"Übungsvariante: Newsletter und Schild zeigen dieselbe Aktion. Im Schild ist die Wegangabe jetzt klar. Der Newsletter nennt aber noch ein mitgeliefertes Netzteil.","ask":"Welche Entscheidung ist fachlich und organisatorisch sinnvoll?","options":["Schild separat am Auftrag und an den Produktblättern prüfen und bei erfüllten Kriterien zur Freigabe vorlegen.","Beide Fassungen als geprüft markieren, weil Thema und Zeitraum stimmen.","Im Newsletter Netzteil durch die belegte Angabe zum USB-C-Ladekabel ersetzen.","Den Newsletter nach der Änderung erneut im vorgesehenen Format lesen und den Aussagencheck aktualisieren.","Das Netzteil im Newsletter stehen lassen, weil es auf dem Schild nicht vorkommt.","Im Schild die richtige Wegangabe streichen, damit beide Formate gleich aussehen."],"answer":[0,2,3],"why":"Beide Formate können separat geprüft werden. Für das L10 ist ein Ladekabel belegt, ein Netzteil nicht. Die Überarbeitung gehört in die Fassung und in den Aussagencheck.","hint":"Prüfe jede Fassung einzeln auf Auftrag, Belege und Lesbarkeit.","steps":"Markiere den konkreten Fehler, ändere ihn und prüfe, ob die neue Formulierung weiterhin verständlich ist.","example":"Eine fertige Fassung kann freigabefähig sein, während die zweite noch nachgebessert wird.","c":1,"sourceRefs":["M1","M2","M5"],"id":23,"l":2,"type":"multi","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die Prüfung starten","scene":"Übungsvariante: Sarah schickt dir am Vormittag beide Rohentwürfe. Jan erwartet bis zum Termin einen überarbeiteten Newsletter für Block und ein Eingangsschild für die Bike Arena. Nutze M1 bis M5.","ask":"Womit beginnst du die Überarbeitung?","options":["Du markierst in beiden Fassungen alle prüfbaren Angaben zu Produkt und Lieferumfang.","Du liest beide Fassungen mit einer Person durch und sammelst erste Fragen zu Verständlichkeit und Nutzen.","Du klärst die zwei Formate, die Vorgaben und die Zeit für Prüfung, Korrektur und Freigabe.","Du ordnest die Text- und Bildelemente ihren Artikelnummern zu und legst M2 bereit.","Du überträgst die beiden Kundenstimmen aus M4 in kurze Fragen, die ihr beim Lesen im Kopf behaltet.","Du teilst die Arbeit an den beiden Entwürfen auf und hältst fest, wer den abschließenden Aussagencheck übernimmt."],"consequences":["Die technischen Versprechen sind gesammelt und lassen sich gezielt mit M2 abgleichen.","Erste offene Stellen zur Verständlichkeit werden sichtbar und können am jeweiligen Werbemittel geprüft werden.","Du kennst den Rahmen für beide Produkte und hast vor der Freigabe Zeit für Korrekturen vorgesehen.","Du kannst ähnliche Artikel unterscheiden und später auch Zeichnungen am passenden Produktblatt prüfen.","Die unterschiedlichen Fragen nach Passform und Orientierung bleiben bei der Überarbeitung sichtbar.","Die zwei Fassungen haben Verantwortliche und erhalten denselben abschließenden Prüfmaßstab."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Wähle, welchen Schwerpunkt du in den weiteren Entscheidungen wieder aufgreifen willst.","steps":"Sieh nach, welche Informationen du zuerst brauchst, um beide Fassungen zuverlässig zu bearbeiten.","example":"Du kannst mit Belegen, Sichtweisen oder Rahmenbedingungen anfangen und alle drei im Verlauf einbeziehen.","c":1,"sourceRefs":["Handlungssituation","M1","M2","M3","M4"],"id":24,"l":3,"type":"story","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen."},{"title":"Die gemeinsame Botschaft setzen","scene":"Die Werbung soll im Auricher Newsletter und am Eingang in Leer als dieselbe Frühjahrsaktion zu erkennen sein. Aus M1 bleiben die Artikel und der gemeinsame Zeitraum fest.","ask":"Wie bringst du die gemeinsame Botschaft in beide Fassungen?","options":["Du prüfst, welche Aussagen in M1 für beide Läden gelten, und überträgst die gemeinsame Botschaft und den Zeitraum in beide Entwürfe.","Du lässt zwei Personen den ersten Eindruck schildern und arbeitest die gemeinsame Botschaft so heraus, dass beide sie erkennen.","Du legst pro Format einen festen Platz für die gemeinsame Botschaft fest und beachtest Absatzlänge und Blickabstand.","Du verfolgst in einer kleinen Gegenüberstellung, welche Aussagen beide Fassungen teilen und welche zum Standort gehören.","Du lässt die Fassungen aus Sicht der Alltagskundschaft und einer Familie lesen und schärfst den gemeinsamen Aktionsbezug.","Du beginnst mit einem passenden Betreff für den Newsletter und einer gut lesbaren Überschrift für das Schild und prüfst die Auftragsvorgaben für beide."],"consequences":["Beide Werbemittel lassen sich am gleichen Werbeauftrag prüfen.","Die Überarbeitung knüpft an das an, was Testlesende zuerst wahrnehmen.","Die gemeinsame Botschaft erhält in jedem Format eine sichtbare Stelle.","Du erkennst schnell, falls eine standortspezifische Aussage versehentlich im anderen Entwurf steht.","Beide Zielgruppen können dieselbe Aktion erkennen, obwohl sie unterschiedliche Informationen brauchen.","Die gemeinsame Kampagne erscheint in einer Form, die zum Handy beziehungsweise zum Eingang passt."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Greife die Richtung aus deinem ersten Schritt auf und achte auf beide Läden.","steps":"Vergleiche den gemeinsamen Inhalt mit dem unterschiedlichen Ort der Werbung.","example":"Dieselbe Botschaft kann in einer kurzen Betreffzeile und in einer großen Schildüberschrift erkennbar sein.","c":0,"sourceRefs":["M1","M4","M5"],"id":25,"l":3,"type":"story","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":24,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Eine heikle Angabe ändern","scene":"Im Newsletter stehen „passt an jeden Lenker“ und „mit Netzteil“. Auf dem Schild hat die Pumpe eine runde Anzeige.","ask":"Wie bearbeitest du die problematischen Angaben?","options":["Du übernimmst für die L10-Halterung die geprüfte Spanne, nennst das Ladekabel und dokumentierst, warum die P50-Anzeige aus dem Bild verschwindet.","Du lässt eine andere Person sagen, was sie aufgrund von Text und Bild erwarten würde, und prüfst diese Eindrücke anschließend einzeln mit M2.","Du planst für beide Werbemittel einen eigenen Kontrollschritt ein, bei dem nicht bestätigte Produkteigenschaften vor der Freigabe gesperrt bleiben.","Du legst die L10- und die P50-Zeile neben die jeweils betroffene Stelle und hältst alte Aussage, Beleg und Korrektur fest.","Du bittest Sarah und die prüfende Person um einen Blick auf die verständliche Neufassung und klärst dabei, welche Erwartungen die Zeichnung weckt.","Du ersetzt das unsichere Pumpenbild durch ein Produktfeld mit Artikelnummer und legst fest, wer die endgültigen Angaben zu jedem Werbemittel prüft."],"consequences":["Die falschen Versprechen werden durch belegte Angaben oder durch eine korrekte Korrektur ersetzt.","Du erkennst auch Erwartungen, die ein Bild auslöst, und hast für die Prüfung eine geeignete Quelle.","Unbelegte Ausstattung kann den vereinbarten Freigabeschritt nicht unbemerkt passieren.","Der Aussagencheck macht nachvollziehbar, welche Information geändert wurde und warum.","Die Neufassung kann fachlich stimmen und trotzdem einfach zu verstehen sein.","Auch ohne eine riskante Zeichnung bleibt erkennbar, welcher Artikel auf dem Schild gemeint ist."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Stelle sicher, dass Text und Bild mit M2 abgeglichen werden.","steps":"Gehe von der betroffenen Stelle zu ihrer Produktangabe. Wie passt dein Vorgehen zu den vorherigen Schritten?","example":"Wenn eine Zeichnung eine Anzeige zeigt, reicht es nicht, nur den Satz über die Anzeige zu löschen.","c":3,"sourceRefs":["M2","M3","M5"],"id":26,"l":3,"type":"story","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":25,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Den nächsten Schritt zeigen","scene":"Im ersten Lesetest erkennen Menschen in Leer die Aktion, finden aber den Hauptgang nicht. Bei Block bleibt nach dem Lesen offen, welche Beratung möglich ist.","ask":"Wie machst du die nächsten Schritte verständlicher?","options":["Du übernimmst aus M1 eine konkrete Wegangabe für Leer und aus M2 eine belegte Frage zur Passform für die Beratung bei Block.","Du fragst je eine Testperson, was sie nach dem Lesen tun würde, und formulierst die Handlungsaufforderung mit ihrer Rückmeldung neu.","Du gibst beiden Handlungsaufforderungen sichtbare Stellen im Format und prüfst Betreff, Handyrahmen und Schildabstand am Entwurf.","Du vergleichst die Wünsche in M4 mit den Entwürfen und ergänzt jeweils den dazu passenden nächsten Schritt.","Du lässt Testlesende den Weg in eigenen Worten nennen und beim Newsletter beschreiben, was sie bei der Beratung klären können.","Du ergänzt den Hauptgang und den Hinweis auf Beratung als fest definierte Elemente der beiden Abschlussfassungen und lässt sie in der vorgesehenen Ansicht prüfen."],"consequences":["Die überarbeitete Werbung nennt konkrete Handlungen, die Auftrag und Produktangaben tragen.","Die neue Formulierung setzt direkt an der fehlenden Orientierung an.","Die nächsten Schritte lassen sich dort wahrnehmen, wo die Fassung tatsächlich gelesen wird.","Der Entwurf greift die unterschiedlichen Fragen auf, die Kundschaft im Fall nennt.","Du hörst, ob Menschen den nächsten Schritt wirklich verstanden haben.","Vor der Freigabe prüft das Team, ob beide verbindlichen Handlungsaufforderungen sichtbar sind."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Frage zuerst, was Menschen nach dem Lesen wissen oder tun sollen.","steps":"Ordne den beiden Standorten je eine nächste Handlung zu und prüfe sie mit deinem Schwerpunkt.","example":"„Zur Beratung bei Block“ passt zu einem anderen Moment als „Zur Aktionsfläche am Hauptgang“.","c":4,"sourceRefs":["M1","M2","M3","M4","M5"],"id":27,"l":3,"type":"story","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":26,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Die Fassungen prüfen","scene":"Übungsvariante: Beide Fassungen liegen vor. Eine Kollegin schlägt vor, nur noch grob über das Schild zu schauen, um Zeit zu sparen.","ask":"Wie nutzt du die verbleibende Zeit für eine sorgfältige Freigabe?","options":["Du prüfst beide letzten Fassungen an M1 und M2 und ergänzt die letzten fehlenden Nachweise im Aussagencheck.","Du organisierst einen kurzen zweiten Lesetest und setzt danach die wichtigsten Rückmeldungen um. Die Produktangaben prüfst du weiterhin mit M2.","Du teilst die letzten Prüfungen nach Format und Verantwortung auf und setzt eine feste Zeit für die gemeinsame Freigabe.","Du gehst im Aussagencheck alte und neue Formulierung mit den tatsächlich freizugebenden Dateien durch.","Du holst aus beiden Standortperspektiven eine Rückmeldung ein und klärst mit der zuständigen Person die letzte offene Formulierung.","Du nutzt eine kurze Freigabeliste für beide Fassungen: richtige Datei, belegte Produktangaben, lesbare Botschaft, passender nächster Schritt."],"consequences":["Die Endfassung ist nachvollziehbar geprüft, auch wenn die knappe Zeit keine weitere Gestaltung zulässt.","Die letzten Anpassungen beruhen auf Verständlichkeit und geprüften Produktdaten.","Die abschließenden Aufgaben sind zeitlich und personell abgesichert.","Die Dokumentation verweist auf die Fassung, die tatsächlich erscheinen soll.","Eine offene Rückmeldung wird konkret geklärt, statt bei der Freigabe übergangen zu werden.","Beide Werbemittel durchlaufen einen einheitlichen Abschluss, der trotzdem die unterschiedlichen Formate berücksichtigt."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Eine schnelle Prüfung soll die wichtigsten Kriterien zuverlässig abdecken.","steps":"Wähle einen Abschluss, der die Entscheidungen aus den vorigen Kapiteln sichtbar fortsetzt.","example":"Ein belegter Text in einer älteren Datei hilft nicht, wenn versehentlich eine neue Version mit unbelegter Aussage freigegeben wird.","c":1,"sourceRefs":["M1","M2","M5"],"id":28,"l":3,"type":"story","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":27,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Die Freigabe begründen","scene":"Jan bekommt beide Endfassungen und will wissen, warum sie eingesetzt werden können. Er hat Zeit für eine kurze Rückmeldung.","ask":"Worauf legst du in deiner Rückmeldung den Schwerpunkt?","options":["Du zeigst je Werbemittel eine korrigierte Produktaussage und den Beleg dafür aus M2.","Du beschreibst eine Rückmeldung der Testlesenden und welche verständlichere Formulierung oder Wegangabe daraus entstanden ist.","Du übergibst beide eindeutig benannten Endfassungen mit Aussagencheck und bestätigten Formatvorgaben.","Du erklärst, wie eure geprüfte gemeinsame Botschaft und die standortspezifischen Handlungen in beiden Fassungen auftauchen.","Du fasst zusammen, warum die Lösung für die Kundschaft von Block und jene der Bike Arena verständlich ist und wie ihr das geprüft habt.","Du nennst die erledigten Prüfungen, den Stand beider Fassungen und wer die endgültige Übergabe an die Läden übernimmt."],"consequences":["Jan kann an einem konkreten Beispiel nachvollziehen, warum er die korrigierten Angaben freigeben kann.","Die Wirkung der Rückmeldung auf die Überarbeitung bleibt in der Entscheidung erkennbar.","Jan kann die beiden richtigen Dateien und ihre Prüfunterlagen zuverlässig weitergeben.","Die Begründung zeigt, wie die gemeinsame Aktion mit zwei unterschiedlichen nächsten Schritten umgesetzt ist.","Die Rückmeldung verbindet die Gestaltung mit dem, was die beiden Zielgruppen tatsächlich verstehen sollen.","Die Endfassungen sind freigegeben oder offen gekennzeichnet und der nächste Zuständigkeitswechsel ist klar."],"why":"Die sechs Vorschläge setzen unterschiedliche Schwerpunkte. Entscheidend ist, wie gut deine Wahl zu den übrigen Schritten deiner Entscheidungskette passt.","hint":"Nenne einen greifbaren Grund, den Jan mit deiner bisherigen Arbeit verbinden kann.","steps":"Schau zurück auf deine vorausgehenden Entscheidungen und wähle die dazu passende Form der Rückmeldung.","example":"Eine Freigabe lässt sich kurz erläutern, indem du eine konkret geänderte Stelle und ihren Prüfgrund zeigst.","c":2,"sourceRefs":["Handlungssituation","M1","M2","M5"],"id":29,"l":3,"type":"story","caseLabel":"LS 6.6 · Werbemittel für beide Standorte gestalten","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":28,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]}];
