const TRANSFER_RULES=[{"id":"r01","label":"Kapitel 1 ↔ Kapitel 2","kind":"matrix","steps":[0,1],"weight":1,"matrix":[[1,0.78,0.78],[0.78,1,0.78],[0.78,0.78,1]],"good":"„Die Prüfung starten“ und „Die gemeinsame Botschaft setzen“ bauen auf demselben Schwerpunkt auf.","issue":"Zwischen „Die Prüfung starten“ und „Die gemeinsame Botschaft setzen“ wechselt dein Schwerpunkt.","next":"Verbinde beim Schritt „Die gemeinsame Botschaft setzen“ deine Handlung mit dem Beleg, der Rückmeldung oder der Vorgabe aus „Die Prüfung starten“."},{"id":"r02","label":"Kapitel 1 ↔ Kapitel 3","kind":"matrix","steps":[0,2],"weight":1.1,"matrix":[[1,0.72,0.72],[0.72,1,0.72],[0.72,0.72,1]],"good":"„Die Prüfung starten“ und „Eine heikle Angabe ändern“ bauen auf demselben Schwerpunkt auf.","issue":"Zwischen „Die Prüfung starten“ und „Eine heikle Angabe ändern“ wechselt dein Schwerpunkt.","next":"Verbinde beim Schritt „Eine heikle Angabe ändern“ deine Handlung mit dem Beleg, der Rückmeldung oder der Vorgabe aus „Die Prüfung starten“."},{"id":"r03","label":"Kapitel 2 ↔ Kapitel 4","kind":"matrix","steps":[1,3],"weight":1,"matrix":[[1,0.84,0.84],[0.84,1,0.84],[0.84,0.84,1]],"good":"„Die gemeinsame Botschaft setzen“ und „Den nächsten Schritt zeigen“ bauen auf demselben Schwerpunkt auf.","issue":"Zwischen „Die gemeinsame Botschaft setzen“ und „Den nächsten Schritt zeigen“ wechselt dein Schwerpunkt.","next":"Verbinde beim Schritt „Den nächsten Schritt zeigen“ deine Handlung mit dem Beleg, der Rückmeldung oder der Vorgabe aus „Die gemeinsame Botschaft setzen“."},{"id":"r04","label":"Kapitel 3 ↔ Kapitel 5","kind":"matrix","steps":[2,4],"weight":1.3,"matrix":[[1,0.72,0.72],[0.72,1,0.72],[0.72,0.72,1]],"good":"„Eine heikle Angabe ändern“ und „Die Fassungen prüfen“ bauen auf demselben Schwerpunkt auf.","issue":"Zwischen „Eine heikle Angabe ändern“ und „Die Fassungen prüfen“ wechselt dein Schwerpunkt.","next":"Verbinde beim Schritt „Die Fassungen prüfen“ deine Handlung mit dem Beleg, der Rückmeldung oder der Vorgabe aus „Eine heikle Angabe ändern“."},{"id":"r05","label":"Kapitel 4 ↔ Kapitel 5","kind":"matrix","steps":[3,4],"weight":1,"matrix":[[1,0.82,0.82],[0.82,1,0.82],[0.82,0.82,1]],"good":"„Den nächsten Schritt zeigen“ und „Die Fassungen prüfen“ bauen auf demselben Schwerpunkt auf.","issue":"Zwischen „Den nächsten Schritt zeigen“ und „Die Fassungen prüfen“ wechselt dein Schwerpunkt.","next":"Verbinde beim Schritt „Die Fassungen prüfen“ deine Handlung mit dem Beleg, der Rückmeldung oder der Vorgabe aus „Den nächsten Schritt zeigen“."},{"id":"r06","label":"Kapitel 5 ↔ Kapitel 6","kind":"matrix","steps":[4,5],"weight":1.8,"matrix":[[1,0.35,0.35],[0.35,1,0.35],[0.35,0.35,1]],"good":"„Die Fassungen prüfen“ und „Die Freigabe begründen“ bauen auf demselben Schwerpunkt auf.","issue":"Zwischen „Die Fassungen prüfen“ und „Die Freigabe begründen“ wechselt dein Schwerpunkt.","next":"Verbinde beim Schritt „Die Freigabe begründen“ deine Handlung mit dem Beleg, der Rückmeldung oder der Vorgabe aus „Die Fassungen prüfen“."}];
